import{_ as o,a,b as r,c as s,d as t,e as n}from"./chunks/wb-universe-settings-region.BXG2sqQw.js";import{_ as i,c as u,o as l,ae as g}from"./chunks/framework.DBgX5bsf.js";const _=JSON.parse('{"title":"Configuration du Thème","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/configuration-theme.md","filePath":"fr/docs/configuration-theme.md"}'),c={name:"fr/docs/configuration-theme.md"};function p(d,e,m,f,h,b){return l(),u("div",null,e[0]||(e[0]=[g('<h1 id="configuration-du-theme" tabindex="-1">Configuration du Thème <a class="header-anchor" href="#configuration-du-theme" aria-label="Permalink to &quot;Configuration du Thème&quot;">​</a></h1><p>Le thème <strong>E-commerce Sale of Bags (ESB)</strong> est un thème Drupal offrant des options de configuration avancées pour personnaliser l&#39;apparence de votre site. Ce thème propose <strong>10 régions</strong>, permettant la création de mises en page complexes. Vous pouvez configurer les couleurs, les polices, les tailles de texte, les options de mise en page, et bien plus encore en suivant le guide de la configuration avancé.<br> Pour accéder aux options de configuration du thème, rendez-vous dans <code>admin/appearance/settings/habeuk_theme</code>.<br><em>Ce thème hérite de la configuration du thème <a href="https://www.drupal.org/project/wb_universe" target="_blank" rel="noreferrer">Wb Universe</a>.</em></p><h3 id="ajout-des-cles-google-analytics-et-facebook-api" tabindex="-1">Ajout des clés Google Analytics et Facebook API <a class="header-anchor" href="#ajout-des-cles-google-analytics-et-facebook-api" aria-label="Permalink to &quot;Ajout des clés Google Analytics et Facebook API&quot;">​</a></h3><ol><li>Créez un compte <strong>Google Analytics</strong> et <strong>Facebook API</strong> pour obtenir les clés d&#39;accès.</li><li>Ajoutez ces clés dans les champs prévus à cet effet dans l&#39;interface d&#39;administration.<br><img src="'+o+'" alt="Google Analytics et Facebook API"></li></ol><h3 id="configuration-du-groupe-pages-templates" tabindex="-1">Configuration du groupe : <strong>Pages Templates</strong> <a class="header-anchor" href="#configuration-du-groupe-pages-templates" aria-label="Permalink to &quot;Configuration du groupe : **Pages Templates**&quot;">​</a></h3><p>Ce groupe permet de configurer les options des pages, notamment la taille des conteneurs pour les différentes pages. Il est divisé en <strong>4 sous-groupes</strong>, chacun contenant des liens de page et un champ <strong>&quot;Select container&quot;</strong>.<br> Le champ <strong>&quot;Select container&quot;</strong> propose 4 options de taille :</p><ul><li><strong>Container</strong> : Affichage moyen (environ 1200px).</li><li><strong>Container-fluid</strong> : Affichage large.</li><li><strong>Width-tablette</strong> : Affichage moyen optimisé pour les tablettes (idéal pour les pages de contenu).</li><li><strong>Width-phone</strong> : Affichage moyen optimisé pour les mobiles.</li></ul><p><img src="'+a+'" alt="Paramètres des modèles de pages Wb Universe"></p><h3 id="configuration-du-groupe-mise-en-page" tabindex="-1">Configuration du groupe : <strong>Mise en Page</strong> <a class="header-anchor" href="#configuration-du-groupe-mise-en-page" aria-label="Permalink to &quot;Configuration du groupe : **Mise en Page**&quot;">​</a></h3><p>Ce groupe permet de configurer l&#39;affichage des colonnes latérales (gauche ou droite) sur vos pages. Vous pouvez également définir la taille des colonnes en utilisant des classes <strong>Bootstrap</strong> ou des classes <strong>CSS</strong> personnalisées (vous devez créer les styles associés à ces classes).<br><img src="'+r+'" alt="Paramètres de mise en page Wb Universe"></p><h3 id="configuration-du-groupe-formulaire" tabindex="-1">Configuration du groupe : <strong>Formulaire</strong> <a class="header-anchor" href="#configuration-du-groupe-formulaire" aria-label="Permalink to &quot;Configuration du groupe : **Formulaire**&quot;">​</a></h3><p>Ce groupe permet d&#39;ajouter des classes <strong>CSS</strong> à vos formulaires. Par exemple, vous pouvez ajouter la classe Bootstrap <strong><code>mb-4</code></strong> pour appliquer une marge en bas.<br><img src="'+s+'" alt="Paramètres des formulaires Wb Universe"></p><h3 id="configuration-du-groupe-menu-display" tabindex="-1">Configuration du groupe : <strong>Menu Display</strong> <a class="header-anchor" href="#configuration-du-groupe-menu-display" aria-label="Permalink to &quot;Configuration du groupe : **Menu Display**&quot;">​</a></h3><p>Ce groupe permet de configurer l&#39;affichage des menus. Vous pouvez choisir entre un affichage <strong>horizontal</strong> (par défaut) ou <strong>vertical</strong>.<br> Pour un affichage vertical, ajoutez la classe <strong><code>flex-column</code></strong> ou <strong><code>navbar-nav</code></strong> dans le champ <strong>&quot;Class menu&quot;</strong>.<br><img src="'+t+'" alt="Paramètres d&#39;affichage des menus Wb Universe"></p><h3 id="configuration-du-groupe-class-css-de-la-region" tabindex="-1">Configuration du groupe : <strong>Class CSS de la Région</strong> <a class="header-anchor" href="#configuration-du-groupe-class-css-de-la-region" aria-label="Permalink to &quot;Configuration du groupe : **Class CSS de la Région**&quot;">​</a></h3><p>Ce groupe permet d&#39;ajouter des classes <strong>CSS</strong> personnalisées à chacune de vos régions.<br><img src="'+n+'" alt="Paramètres des régions Wb Universe"></p><h3 id="configuration-du-groupe-config-tables" tabindex="-1">Configuration du groupe : <strong>Config Tables</strong> <a class="header-anchor" href="#configuration-du-groupe-config-tables" aria-label="Permalink to &quot;Configuration du groupe : **Config Tables**&quot;">​</a></h3><p>Ce groupe permet d&#39;ajouter des classes <strong>CSS</strong> aux tableaux.</p><ul><li>Pour le champ <strong>&quot;Custom class for tag table&quot;</strong>, vous pouvez ajouter les classes <strong><code>mb-4 table table-striped</code></strong>.</li><li>Pour le champ <strong>&quot;Custom class for container&quot;</strong>, vous pouvez ajouter les classes <strong><code>border border-radius-10 px-5 py-4 mb-4</code></strong>.</li></ul><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>Le thème <strong>E-commerce Sale of Bags (ESB)</strong> offre une grande flexibilité pour personnaliser l&#39;apparence et la structure de votre site. Vous pouvez ajuster les couleurs, les tailles de police, et bien d&#39;autres paramètres en explorant les options disponibles. Pour des personnalisations supplémentaires, consultez les paramètres avancés du thème.</p>',21)]))}const P=i(c,[["render",p]]);export{_ as __pageData,P as default};
